import{c as t,Q as r,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Zeuik's Claude Code Docs","text":"Claude Code Harness 工程課程","tagline":"從 CLAUDE.md 設計到驗證迴圈與組織治理，掌握讓 AI Agent 真正可靠的工程方法。十二堂課，四個實作專案，全部接地於官方一手來源。","actions":[{"theme":"brand","text":"開始學習 ->","link":"/lectures/"},{"theme":"alt","text":"實作專案","link":"/projects/"},{"theme":"alt","text":"研究資料庫","link":"/research/"},{"theme":"alt","text":"GitHub ↗","link":"https://github.com/zeuikli/cc-workspace-docs"}]},"features":[{"icon":"🧠","title":"Harness 工程理論","details":"深入理解 Agent = Model + Body + Harness 等式。量化數據證明：同一個模型，不同 Harness 造成 7–23pp 的效能差距。"},{"icon":"📄","title":"CLAUDE.md 與規則設計","details":"四層作用域、Ratchet 原則、觸發點判斷表。以及 2026 年的新變數——規則不是零成本，衝突指令會消耗模型的推理預算。"},{"icon":"🔄","title":"Context Engineering","details":"Context Rot 的量化機制（18 個模型全部隨 context 增長下降），Claude 5 世代六條新規則，以及五個會炸掉 prompt cache 的操作。"},{"icon":"🏗️","title":"三層 Harness 架構","details":"Planner / Generator / Evaluator 分離設計。為什麼 Generator 不能自評？25 種 Hooks 事件如何構建防禦層？"},{"icon":"🧩","title":"Skills 與 Sub-agents","details":"九大 Skill 類別、自由度校準、Progressive Disclosure；委派的硬門檻、五種協調模式、六種 Dynamic Workflow 模式。"},{"icon":"⚖️","title":"模型選型與 Effort","details":"class × effort 的二維框架。為什麼「每 token 價格」不等於「每任務價格」？Advisor 策略如何取得 90% 效能而只付 63% 成本？"},{"icon":"✅","title":"驗證迴圈","details":"獨立 verifier 讓 false positive 減半。Oracle 先驗、裝完成的六種捷徑、REVIEW.md 收斂——驗證的觸發權在 harness，不在模型。"},{"icon":"🔒","title":"安全與治理","details":"環境層優先於模型層。Filesystem + Network 雙重隔離、六類 agentic 漏洞、CISO 四問、Vault 憑證邊界替換。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785912489000}`),a={name:"index.md"};function l(s,e,i,d,c,g){return r(),o("div",null,[...e[0]||(e[0]=[n('<h2 id="關於本課程" tabindex="-1">關於本課程 <a class="header-anchor" href="#關於本課程" aria-label="Permalink to &quot;關於本課程&quot;">​</a></h2><p>本課程源自 <strong>Zeuik 的私有 cc-workspace</strong>，整理了 SRE / Cloud Architect 視角下對 Claude Code Workspace 的深度研究。</p><p>課程以 <strong>Harness Engineering</strong> 為主軸，從理論到實作，幫助你把 Claude Code 這類 AI Agent 從「不可靠」變成「生產可用」。每一堂課都標註官方一手來源，可以追溯回 Anthropic 的原始文件與工程部落格。</p><p><strong>內容規模</strong>：</p><ul><li><strong>12 堂課程講義</strong> — 基礎 → 架構 → 擴展 → 工程化</li><li><strong>4 個實作專案</strong> — 建立 workspace → 設計 harness → 驗證資產化 → 推廣成基礎建設</li><li><strong>研究資料庫</strong> — 315 篇論文歸檔、深度研究報告、49 篇最佳實踐、<a href="/cc-workspace-docs/research/claude-blog/">153 個官方 blog 條目</a>（2025-11 ~ 2026-07）</li></ul><h2 id="適合誰閱讀" tabindex="-1">適合誰閱讀 <a class="header-anchor" href="#適合誰閱讀" aria-label="Permalink to &quot;適合誰閱讀&quot;">​</a></h2><ul><li>想讓 Claude Code / Codex 在真實專案中可靠工作的工程師</li><li>對 LLM Agent 架構設計感興趣的開發者</li><li>需要為團隊建立 AI 開發規範與護欄的技術主管</li><li>關心 agentic 系統安全邊界的 SRE 與資安工程師</li></ul><h2 id="學習路徑" tabindex="-1">學習路徑 <a class="header-anchor" href="#學習路徑" aria-label="Permalink to &quot;學習路徑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>階段</th><th>內容</th><th>產出</th><th>預估時間</th></tr></thead><tbody><tr><td><strong>基礎</strong></td><td>Lecture 01–03：Harness 等式、CLAUDE.md、Context Engineering</td><td>可跨 session 記憶的 workspace</td><td>4 小時</td></tr><tr><td><strong>架構</strong></td><td>Lecture 04–06：三層架構、Memory / Worktree、安全沙箱</td><td>有獨立驗證與安全邊界的 harness</td><td>5 小時</td></tr><tr><td><strong>擴展</strong></td><td>Lecture 07–09：Skills、Sub-agents / Workflows、模型選型</td><td>可重用的 Skill 與成本策略</td><td>4 小時</td></tr><tr><td><strong>工程化</strong></td><td>Lecture 10–12：驗證迴圈、MCP、Plugins 與治理</td><td>團隊可安裝的 plugin 與自動化</td><td>4 小時</td></tr></tbody></table><p>按角色的建議切入點見<a href="/cc-workspace-docs/lectures/">課程總覽</a>。</p><h2 id="_2026-年的三個轉向" tabindex="-1">2026 年的三個轉向 <a class="header-anchor" href="#_2026-年的三個轉向" aria-label="Permalink to &quot;2026 年的三個轉向&quot;">​</a></h2><p>如果你以前讀過類似的內容，這三件事在 2026 下半年<strong>反轉</strong>了，值得先知道：</p><ol><li><strong>從「堆規則」轉向「信任判斷」</strong> — Anthropic 為 Claude 5 世代刪掉 Claude Code system prompt 的 <strong>80% 以上</strong>，coding evals 無可量測退化。多加一條保險條文不是零成本。</li><li><strong>驗證的觸發權從模型收回 harness</strong> — <code>/verify</code>、<code>/code-review</code>、<code>/deep-research</code> 都改為手動呼叫。任何假設「模型會自己 review」的流程都已失效。</li><li><strong>扇出從「越多越好」轉向「有界治理」</strong> — subagent 上限、預設不巢狀 spawn、預算真正止血、背景 session 收尾語義明確化。</li></ol><p>完整論述見 <a href="/cc-workspace-docs/research/claude-blog/docs/synthesis">claude-blog 跨主題合成</a>。</p><h2 id="關鍵參考資料" tabindex="-1">關鍵參考資料 <a class="header-anchor" href="#關鍵參考資料" aria-label="Permalink to &quot;關鍵參考資料&quot;">​</a></h2><blockquote><p>本課程的理論基礎來自以下一手來源：</p></blockquote><p><strong>Harness 工程</strong></p><ul><li><a href="https://www.anthropic.com/engineering/harness-design-long-running-apps" target="_blank" rel="noreferrer">Anthropic: Harness design for long-running application development</a></li><li><a href="https://www.anthropic.com/engineering/effective-harnesses-for-long-running-agents" target="_blank" rel="noreferrer">Anthropic: Effective harnesses for long-running agents</a></li><li><a href="https://openai.com/index/harness-engineering/" target="_blank" rel="noreferrer">OpenAI: Harness engineering — leveraging Codex in an agent-first world</a></li><li><a href="https://www.langchain.com/blog/improving-deep-agents-with-harness-engineering" target="_blank" rel="noreferrer">LangChain: Improving Deep Agents with harness engineering</a></li></ul><p><strong>Claude 5 世代</strong></p><ul><li><a href="https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models" target="_blank" rel="noreferrer">The new rules of context engineering for Claude 5 generation models</a>（2026-07-24）</li><li><a href="https://claude.com/blog/claude-models-explained-choosing-the-best-model-for-your-use-case" target="_blank" rel="noreferrer">Claude models explained: choosing the best model for your use case</a>（2026-07-24）</li><li><a href="https://claude.com/blog/building-verification-loops-in-claude-code-with-skills" target="_blank" rel="noreferrer">Building verification loops in Claude Code with skills</a>（2026-07-22）</li><li><a href="https://claude.com/blog/steering-claude-code-skills-hooks-rules-subagents-and-more" target="_blank" rel="noreferrer">Steering Claude Code: CLAUDE.md files, skills, hooks, rules, subagents and more</a>（2026-06-18）</li></ul><p><strong>安全與治理</strong></p><ul><li><a href="https://www.anthropic.com/engineering/how-we-contain-claude" target="_blank" rel="noreferrer">Anthropic: How we contain Claude across products</a></li><li><a href="https://claude.com/blog/ciso-guide-to-agentic-ai" target="_blank" rel="noreferrer">Zero risk isn&#39;t the job: a CISO&#39;s guide to agentic AI</a>（2026-07-17）</li><li><a href="https://claude.com/blog/zero-trust-for-ai-agents" target="_blank" rel="noreferrer">Zero Trust for AI agents</a>（2026-05-27）</li></ul><p><strong>Context Rot</strong></p><ul><li><a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">Chroma: Context Rot Research</a></li></ul><hr><blockquote><p>內容同步自 <a href="https://github.com/zeuikli/cc-workspace" target="_blank" rel="noreferrer">私有 cc-workspace</a>，已排除個人職涯記錄（career-wiki）與敏感設定。 研究資料庫收錄截止：2026-07-28 · 最後更新：2026-08-05</p></blockquote>',26)])])}const p=t(a,[["render",l]]);export{u as __pageData,p as default};
